import json
n=17; center=8
g=[]
for r in range(n):
 row=[]
 for c in range(n):
  if c==center-r or c==center+r: row.append(2)
  elif abs(c-center)<=r and (c-r-center)%4==0: row.append(1)
  else: row.append(0)
 g.append(row)
assert len(g)==17 and all(len(r)==17 for r in g)
print(json.dumps({'action':'submit','grid':g},separators=(',',':')))
print('VALIDATED',len(g),[len(r) for r in g])
